(() => {
'use strict';
const P=window.Portal,D=window.PartnerLearningContent;if(!P||!D)return;
const A=P.prototypeUsers,e=P.e,modules=D.modules,byId=id=>modules.find(m=>m.id===id),basic=modules.slice(0,5).map(m=>m.id);
let selected='',context='',attempt=null,feedback=null;
const current=()=>A?.current(),eligible=()=>!!current()&&['seller','manager','admin','internal'].includes(current().role);
const isObject=v=>!!v&&typeof v==='object'&&!Array.isArray(v);
const raw=()=>P.state.learningProgram;
const valid=()=>raw()===undefined||(isObject(raw())&&raw().schema===1&&isObject(raw().people)&&isObject(raw().policies)&&Array.isArray(raw().audit)&&Object.values(raw().people).every(isObject)&&Object.values(raw().policies).every(ids=>Array.isArray(ids)&&ids.every(id=>typeof id==='string'&&byId(id))));
const state=()=>valid()?(raw()||{schema:1,people:{},policies:{},audit:[]}):null;
const person=id=>state()?.people[id]||{};
function passed(id,user=current()?.id){const m=byId(id),r=person(user)[id];return !!(m&&r&&r.version===m.version&&r.revision===D.revision&&r.score===m.questions.length&&r.total===m.questions.length&&r.passedAt&&m.prerequisites.every(p=>passed(p,user)));}
const ready=(m,user=current()?.id)=>m.prerequisites.every(p=>passed(p,user));
function commit(fn){if(!valid())return {ok:false,message:'Utbildningsunderlaget kan inte läsas. Ladda om eller kontakta Kraftringen; inga uppgifter har skrivits över.'};const before=raw(),next=JSON.parse(JSON.stringify(state()));const result=fn(next);P.state.learningProgram=next;if(!P.save()){if(before===undefined)delete P.state.learningProgram;else P.state.learningProgram=before;return {ok:false,message:'Resultatet kunde inte sparas. Momentet är inte godkänt. Ladda om vid flikkonflikt och gör om provet.'};}return result||{ok:true};}
function closure(ids){return [...new Set(ids.flatMap(id=>byId(id)?[...closure(byId(id).prerequisites),id]:[]))];}
const key=(category,product)=>category+'|'+product;
function defaults(category,product){let specific=product.includes('Individuell')?'individual':product.includes('Pool')?'pool':product.includes('Direkt')?'direct':product.includes('Stabil')?'stable':'';return [...basic,...(category==='business'&&specific?[specific]:[])];}
function required(category,product){const config=state()?.policies[key(category,product)];return closure(Array.isArray(config)?config:defaults(category,product));}
function check(category,product){if(!current())return {ok:false,message:'Logga in innan du skapar en order.',missing:[]};if(A.internal())return {ok:true,missing:[]};if(!eligible())return {ok:false,message:'Ditt konto kan inte lägga partnerordrar.',missing:[]};if(!valid())return {ok:false,message:'Utbildningsunderlaget kan inte läsas. Kontakta Kraftringen.',missing:[]};const missing=required(category,product).filter(id=>!passed(id));return {ok:!missing.length,missing,message:missing.length?'Utbildning krävs: '+missing.map(id=>byId(id).title).join(', ')+'. Öppna Utbildning och klara momenten före orderläggning.':''};}
const shuffle=values=>values.map(v=>({v,r:Math.random()})).sort((a,b)=>a.r-b.r).map(x=>x.v);
function start(id){const m=byId(id);if(!eligible()||!valid()||!m||!ready(m))return {ok:false,message:'Slutför föregående moment först.'};attempt={token:P.newId(),actor:current().id,module:id,revision:D.revision,questions:shuffle(m.questions.map(q=>q.id)),options:Object.fromEntries(m.questions.filter(q=>q.options).map(q=>[q.id,shuffle(q.options.map((_,i)=>i))]))};feedback=null;return {ok:true,token:attempt.token};}
function submit(token,answers){const t=attempt,m=byId(t?.module);if(!t||t.token!==token||current()?.id!==t.actor||!eligible()||!ready(m)||t.revision!==D.revision)return {ok:false,message:'Provet är inte längre giltigt. Starta om för ditt konto.'};
const results=m.questions.map(q=>{const value=answers?.[q.id];let correct=false;if(q.options){const selected=Array.isArray(value)?value:[];correct=selected.length===q.correct.length&&new Set(selected).size===selected.length&&selected.every(v=>Number.isInteger(v)&&q.correct.includes(v));}else {const s=String(value??'').trim().replace(',','.');correct=/^-?\d+(\.\d+)?$/.test(s)&&Math.abs(Number(s)-q.answer)<0.000001;}return {id:q.id,correct,why:q.why};});
const score=results.filter(r=>r.correct).length,passedAll=score===m.questions.length;
const saved=commit(s=>{const user=s.people[t.actor]||(s.people[t.actor]={}),old=user[m.id]||{};user[m.id]={...old,attempts:(old.attempts||0)+1,lastScore:score,lastAttemptAt:new Date().toISOString(),...(passedAll?{version:m.version,revision:D.revision,score,total:m.questions.length,passedAt:new Date().toISOString()}: {})};return {ok:true};});
if(!saved.ok)return saved;attempt=null;feedback={module:m.id,score,total:m.questions.length,passed:passedAll,results};return {ok:true,...feedback};}
function configure(category,product,ids){if(!A.admin())return {ok:false,message:'Endast Kraftringens administratör kan ändra utbildningskraven.'};if(!P.orderWorkspace?.products[category]?.includes(product)||!Array.isArray(ids)||ids.some(id=>!byId(id)))return {ok:false,message:'Välj en giltig produkt och giltiga moment.'};return commit(s=>{const k=key(category,product);s.audit.push({at:new Date().toISOString(),actor:current().id,product:k,before:s.policies[k]||defaults(category,product),after:closure(ids)});s.policies[k]=closure(ids);return {ok:true};});}
function gate(category,product){const c=check(category,product);return c.ok?'':`<div class="lp-warning" role="status"><strong>Utbildning krävs före orderläggning</strong><p>${e(c.message)}</p><button type="button" class="btn btn-secondary" data-lp-go>Öppna utbildningen</button><small>Eventuella osparade formulärfält följer inte med. Redan sparade utkast bevaras.</small></div>`;}
function sync(){const user=current()?.id||'';if(context!==user){context=user;selected='';attempt=null;feedback=null;}}
function statusText(m){return passed(m.id)?'Godkänd':ready(m)?'Ej godkänd ännu':'Förkunskaper återstår';}
function sourceList(m){return `<div class="lp-sources"><strong>Källor och underlag</strong><ul>${m.sources.map(id=>`<li><a href="${e(D.sources[id][1])}" target="_blank" rel="noopener">${e(D.sources[id][0])}</a></li>`).join('')}${m.category==='Företagsprodukter'?'<li>Kraftringens fyra produktbilder, tillhandahållna av beställaren. Exakta prisformler och avtalsvillkor behöver produktägarens kontroll.</li>':''}</ul><small>Sakgranskning av offentliga källor: 10 november 2026. Inga livepriser. Kursversion ${e(D.revision)}.</small></div>`;}
const fields={balance:[['plan','Planerat inköp (MWh)',80,0,200],['actual','Faktisk förbrukning (MWh)',95,0,200]],price:[['low','Förbrukning vid 50 öre (kWh)',100,0,500],['high','Förbrukning vid 150 öre (kWh)',300,0,500]],hedge:[['secured','Säkrad volym (MWh)',80,0,150],['used','Faktisk förbrukning (MWh)',100,10,200]],direct:[['jan','Januaris säkringsvärde (kr)',6000,0,12000],['feb','Februaris säkringsvärde (kr)',3000,0,12000],['mar','Mars säkringsvärde (kr)',3000,0,12000]],stable:[['jan','Januaris säkringsvärde (kr)',6000,0,12000],['feb','Februaris säkringsvärde (kr)',3000,0,12000],['mar','Mars säkringsvärde (kr)',3000,0,12000]]};
function widget(m){if(m.widget==='grid')return `<section class="lp-lab"><h3>Utforska nätet</h3><p>Välj en del för att se ansvar och anslutningar.</p><div class="lp-pills">${['Transmissionsnät','Regionnät','Lokalnät','Elhandel'].map((v,i)=>`<button class="btn btn-secondary" data-lp-network="${i}" aria-pressed="false">${v}</button>`).join('')}</div><p id="lp-net-result" role="status">El kan produceras och användas på flera nivåer i nätet.</p></section>`;
if(m.widget==='market')return `<section class="lp-lab"><h3>Utforska elområden</h3><label>Överföringsscenario<select id="lp-market"><option value="free">Gott om överföringskapacitet</option><option value="limited">Begränsad överföring till ett område med högre efterfrågan</option></select></label><div id="lp-market-result" role="status"></div><small>Förenklad illustration med påhittade priser, ingen prognos eller verklig nätberäkning.</small></section>`;
return `<section class="lp-lab"><h3>Pröva själv</h3><p>${['direct','stable'].includes(m.widget)?'Illustration i kronor: ändra periodernas säkringsvärden och jämför Direkt med en jämn fördelning. Detta fastställer inte produkternas prisformel.':'Ändra värdena och förklara för dig själv varför utfallet ändras.'}</p><div class="lp-inputs">${(fields[m.widget]||[]).map(([id,label,value,min,max])=>`<label>${label}<input type="range" data-lp-value="${id}" min="${min}" max="${max}" step="${max>500?100:5}" value="${value}"><output data-lp-label="${id}">${value}</output></label>`).join('')}</div><div id="lp-lab-result" role="status"></div><small>Antagna värden. Ingen offert, prisprognos eller fullständig avräkningsmodell.</small></section>`;}
const fmt=n=>new Intl.NumberFormat('sv-SE',{maximumFractionDigits:2}).format(n);
function lab(m){const read=id=>Number(document.querySelector(`[data-lp-value="${id}"]`)?.value||0);document.querySelectorAll('[data-lp-value]').forEach(el=>document.querySelector(`[data-lp-label="${el.dataset.lpValue}"]`).textContent=fmt(Number(el.value)));
const target=document.querySelector('#lp-lab-result');if(target){let text='';if(m.widget==='balance'){const diff=read('actual')-read('plan');text=diff>0?`Underskott: ${fmt(diff)} MWh. Planen behöver justeras; kostnaden kan inte räknas ut utan avräkningspris.`:diff<0?`Överskott: ${fmt(-diff)} MWh. Även överskott behöver hanteras.`:'Plan och faktisk förbrukning matchar i detta exempel.';}
if(m.widget==='price'){const sum=read('low')+read('high'),cost=read('low')*.5+read('high')*1.5;text=sum?`Spotkostnad ${fmt(cost)} kr. Förbrukningsvägt pris ${fmt(cost/sum*100)} öre/kWh. Med 5 öre påslag och 40 kr fast avgift: ${fmt(cost+sum*.05+40)} kr, exkl. moms, nät och andra kostnader.`:'Ingen förbrukning: medelpris kan inte beräknas. Den antagna fasta avgiften är fortfarande 40 kr.';}
if(m.widget==='hedge')text=`Faktisk säkringsgrad: ${fmt(read('secured')/read('used')*100)} %. ${read('secured')>read('used')?'Säkrad volym överstiger användningen. Kontrollera avtalets hantering av översäkring.':'En målandel garanterar inte samma faktiska andel.'}`;
if(['direct','stable'].includes(m.widget)){const vals=['jan','feb','mar'].map(read),mean=vals.reduce((s,v)=>s+v,0)/3;target.innerHTML=`<div class="lp-compare">${['Periodvärden · Direkt','Jämn fördelning · Stabil'].map((title,i)=>`<div><h4>${title}</h4>${vals.map((v,j)=>`<div class="lp-bar"><span>${['Jan','Feb','Mar'][j]}</span><meter min="0" max="12000" value="${i?mean:v}">${fmt(i?mean:v)}</meter><strong>${fmt(i?mean:v)} kr</strong></div>`).join('')}</div>`).join('')}</div><p>Samma totalvärde: ${fmt(mean*3)} kr. Visar fördelningsprincipen, inte kundens totalfaktura.</p>`;return;}target.textContent=text;}
const market=document.querySelector('#lp-market-result');if(market){const limited=document.querySelector('#lp-market').value==='limited';market.innerHTML=`<div class="lp-areas">${['SE1','SE2','SE3','SE4'].map((v,i)=>`<div><strong>${v}</strong><span>${limited?[40,40,65,90][i]:50} öre/kWh</span></div>`).join('')}</div><p>${limited?'Begränsad överföring kan ge olika områdespriser. Den exakta skillnaden beror på bud och kapacitet.':'När överföringen räcker kan områdespriser sammanfalla. Det är ingen garanti för samma pris alla perioder.'}</p>`;}}
function quiz(m){if(!ready(m))return `<div class="lp-warning">Provet öppnas när följande moment är godkända: ${m.prerequisites.map(id=>e(byId(id).title)).join(', ')}.</div>`;
if(attempt?.module===m.id){return `<form id="lp-quiz"><h3>Kunskapsprov · ${m.questions.length} frågor</h3><p>Alla frågor måste vara rätt i samma försök. Flervalsfrågor anger hur många alternativ du ska välja. Svarsalternativens ordning varierar mellan försök.</p>${attempt.questions.map((id,i)=>{const q=m.questions.find(q=>q.id===id);return `<fieldset><legend>${i+1}. ${e(q.prompt)}</legend>${q.options?`<p>Välj ${q.correct.length} alternativ.</p>${attempt.options[id].map(idx=>`<label class="lp-option"><input type="${q.correct.length>1?'checkbox':'radio'}" name="${id}" value="${idx}"> <span>${e(q.options[idx])}</span></label>`).join('')}`:`<label>Ditt svar (${e(q.unit)})<input type="text" inputmode="decimal" name="${id}" autocomplete="off" required></label>`}</fieldset>`;}).join('')}<p id="lp-exam-error" role="alert"></p><button class="btn btn-primary" type="submit">Lämna in alla svar</button></form>`;}
return `${feedback?.module===m.id?`<section class="lp-feedback" role="status"><h3>${feedback.passed?'Godkänd och sparad':'Inte godkänd ännu'} · ${feedback.score}/${feedback.total}</h3><p>${feedback.passed?'Du kan gå vidare.':'Läs återkopplingen och repetera. Gör sedan ett nytt fullständigt prov.'}</p>${feedback.results.map(r=>`<p><strong>${r.correct?'Rätt':'Repetera'}:</strong> ${e(r.why)}</p>`).join('')}</section>`:''}<button class="btn btn-primary" id="lp-start">${passed(m.id)?'Öva igen':feedback?.module===m.id?'Gör ett nytt försök':'Starta kunskapsprov'}</button>${passed(m.id)?'<p>Ett senare övningsförsök tar inte bort ett redan godkänt resultat för samma version.</p>':''}`;}
function render(){sync();if(!eligible())return '<p>Logga in med ett partner- eller Kraftringenkonto för att gå utbildningen.</p>';const m=byId(selected),count=modules.filter(m=>passed(m.id)).length;return `<section class="lp-page"><header class="lp-head"><div><span class="eyebrow">Kraftringen · säljarutbildning</span><h1>${m?e(m.title):'Kunskap som öppnar nästa steg'}</h1><p>Förstå, tillämpa och visa vad du kan.</p></div><button class="btn btn-secondary" data-go="academy-library">Filmer & tidigare material</button></header><div class="lp-banner"><div><strong>${e(current().name)}</strong><span>${count} av ${modules.length} moment godkända</span></div><progress max="${modules.length}" value="${count}">${count}/${modules.length}</progress><span>${count===modules.length?'Godkänd i hela utbildningsprogrammet':'Pågående utbildningsprogram'}</span></div><p class="lp-local">Personliga resultat för ditt demokonto i denna webbläsare. Äldre klarmarkeringar räknas inte som godkända prov. Detta är en prototyp, ingen verifierad yrkescertifiering.</p>${!valid()?'<p class="lp-warning" role="alert">Utbildningsdata kan inte läsas. Inga resultat eller krav skrivs över. Kontakta Kraftringen.</p>':''}<div class="lp-layout"><nav class="lp-menu" aria-label="Utbildningsmoment">${modules.map((m,i)=>`<button data-lp-open="${m.id}" aria-current="${selected===m.id?'step':'false'}"><span>${String(i+1).padStart(2,'0')} · ${e(m.category)}</span><strong>${e(m.title)}</strong><small>${statusText(m)} · ca ${m.minutes} min</small></button>`).join('')}</nav><div class="lp-main">${m?`<article class="lp-lesson"><div class="lp-section-head"><span class="pill">${statusText(m)}</span><button class="text-button" data-lp-home>Utbildningsöversikt</button></div>${P.learningFilms?.render(m)||''}<details class="lf-transcript"><summary>Sammanfattning av grunderna</summary>${m.sections.map(([h,p])=>`<section><h2>${e(h)}</h2><p>${e(p)}</p></section>`).join('')}</details>${widget(m)}<section class="lp-assessment">${quiz(m)}</section>${sourceList(m)}</article>`:overview()}${A.internal()?adminPanel():''}</div></div></section>`;}
function overview(){const products=P.orderWorkspace.products;return `<article class="lp-lesson"><h2>Din väg till godkänd orderläggning</h2><p>Börja med elsystemet och följ grundmomenten i ordning. Varje moment avslutas med tre tillämpningsfrågor. Alla tre måste vara rätt i samma försök. Därefter öppnas produktfördjupningarna och ett avslutande kundfall.</p><button class="btn btn-primary" data-lp-open="${modules.find(m=>!passed(m.id)&&ready(m))?.id||'grid'}">Fortsätt utbildningen →</button><h3>Utbildningskrav för produkter</h3><p>Godkända moment återanvänds för andra produkter som ställer samma krav. Kraftringens administratör kan ändra kraven nedan. Befintliga ordrar och resultat bevaras.</p><div class="table-wrap"><table><thead><tr><th>Produkt</th><th>Krav</th><th>Din status</th></tr></thead><tbody>${Object.entries(products).flatMap(([cat,ps])=>ps.filter(p=>A.internal()||P.productCatalog?.allowed(cat,p,P.partner)).map(p=>{const ids=required(cat,p),missing=ids.filter(id=>!passed(id));return `<tr><th>${e(p)}<small>${cat==='consumer'?'Privat':'Företag'}</small></th><td>${ids.map(id=>e(byId(id).title)).join(', ')||'Inga utbildningskrav'}</td><td>${missing.length?`${missing.length} moment återstår`:'Godkänd för produktens utbildningskrav'}</td></tr>`;})).join('')}</tbody></table></div><p>Övriga produkt- och partnerbehörigheter gäller fortfarande. Kraftringens interna handläggning är undantagen från säljarspärren.</p></article>`;}
function adminPanel(){const users=A.users().filter(u=>['seller','manager'].includes(u.role));return `<details class="lp-lesson"><summary>Kraftringen · utbildningsuppföljning${A.admin()?' och krav':''}</summary><h3>Personliga godkännanden</h3><div class="table-wrap"><table><thead><tr><th>Användare</th><th>Partner</th><th>Godkända moment</th></tr></thead><tbody>${users.map(u=>`<tr><th>${e(u.name)}${u.active?'':' (inaktiv)'}</th><td>${e(P.partners[u.partner]||u.partner)}</td><td>${modules.filter(m=>passed(m.id,u.id)).map(m=>`${e(m.title)} (${e(person(u.id)[m.id].passedAt.slice(0,10))})`).join(', ')||'Inga godkända prov'}</td></tr>`).join('')}</tbody></table></div>${A.admin()?`<h3>Krav per produkt · gäller alla partners med produkten</h3><form id="lp-policy"><label>Produkt<select id="lp-policy-product">${Object.entries(P.orderWorkspace.products).flatMap(([cat,ps])=>ps.map(p=>`<option value="${e(key(cat,p))}">${cat==='consumer'?'Privat':'Företag'} · ${e(p)}</option>`)).join('')}</select></label><fieldset><legend>Moment som krävs</legend>${modules.map(m=>`<label class="lp-option"><input type="checkbox" name="required" value="${m.id}"> ${e(m.title)}</label>`).join('')}</fieldset><p>Förkunskapsmoment läggs automatiskt till. Avmarkera alla för att uttryckligen ta bort utbildningskravet för vald produkt. Ändringen påverkar nya orderförsök och skickande av utkast, inte redan registrerade ordrar.</p><button class="btn btn-primary">Spara utbildningskrav</button><p role="status" id="lp-policy-status"></p></form><details><summary>Senaste kravändringar</summary><ul>${(state()?.audit||[]).slice(-10).reverse().map(a=>`<li>${e(a.at)} · ${e(a.product)} · ${e(a.actor)} · ${(a.after||[]).map(e).join(', ')||'Inga krav'}</li>`).join('')||'<li>Standardkraven används.</li>'}</ul></details>`:'<p>Endast Kraftringens administratör ändrar kraven.</p>'}</details>`;}
function bind(){const view=document.querySelector('#view'),m=byId(selected);view.querySelectorAll('[data-lp-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.lpOpen;attempt=null;feedback=null;P.render();document.querySelector('.lp-main')?.scrollIntoView({block:'start'});});view.querySelector('[data-lp-home]')?.addEventListener('click',()=>{selected='';attempt=null;feedback=null;P.render();});view.querySelector('#lp-start')?.addEventListener('click',()=>{const r=start(selected);if(!r.ok)P.toast(r.message);else P.render();});view.querySelector('#lp-quiz')?.addEventListener('submit',ev=>{ev.preventDefault();const form=ev.target,answers={};for(const q of m.questions)answers[q.id]=q.options?[...form.querySelectorAll(`[name="${q.id}"]:checked`)].map(x=>Number(x.value)):form.elements[q.id].value;const r=submit(attempt?.token,answers);if(!r.ok){form.querySelector('#lp-exam-error').textContent=r.message;return;}P.render();document.querySelector('.lp-assessment')?.scrollIntoView({block:'start'});});
view.querySelectorAll('[data-lp-value]').forEach(el=>el.oninput=()=>lab(m));view.querySelector('#lp-market')?.addEventListener('change',()=>lab(m));if(m){lab(m);P.learningFilms?.bind(m);}
const descriptions=['Transmissionsnät: stora elflöden över långa avstånd. Svenska kraftnät förvaltar nätet.','Regionnät: kopplar samman transmissionsnät, lokalnät och vissa större anläggningar.','Lokalnät: ansluter hushåll och många verksamheter. Lokal produktion kan också mata in el.','Elhandel: köp och försäljning av el enligt avtal. Ett leverantörsbyte flyttar inte nätanslutningen.'];view.querySelectorAll('[data-lp-network]').forEach(b=>b.onclick=()=>{view.querySelectorAll('[data-lp-network]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));view.querySelector('#lp-net-result').textContent=descriptions[Number(b.dataset.lpNetwork)];});
const policy=view.querySelector('#lp-policy');if(policy){const fill=()=>{const [cat,p]=policy.querySelector('select').value.split('|'),ids=required(cat,p);policy.querySelectorAll('[name="required"]').forEach(c=>c.checked=ids.includes(c.value));};policy.querySelector('select').onchange=fill;fill();policy.onsubmit=ev=>{ev.preventDefault();const [cat,p]=policy.querySelector('select').value.split('|');const r=configure(cat,p,[...policy.querySelectorAll('[name="required"]:checked')].map(c=>c.value));policy.querySelector('[role="status"]').textContent=r.ok?'Kraven har sparats lokalt. Förkunskaper ingår.':r.message;if(r.ok)fill();};}}
const legacy=P.routes.academy;P.register('academy-library',legacy);P.register('academy',{render,bind});
P.learningProgram={modules,passed,ready,check,gate,start,submit,configure,required};
document.addEventListener('click',ev=>{if(ev.target.closest('[data-lp-go]')){P.closeDialog();P.go('academy');}});
window.addEventListener('storage',ev=>{if(ev.key==='partnerlabb.portal.v2'){attempt=null;feedback=null;}});
})();
